import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Mock Design Spec","description":"","frontmatter":{},"headers":[],"relativePath":"MOCK-DESIGN.md","filePath":"MOCK-DESIGN.md"}'),r={name:"MOCK-DESIGN.md"};function i(s,t,l,n,h,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="mock-design-spec" tabindex="-1">Mock Design Spec <a class="header-anchor" href="#mock-design-spec" aria-label="Permalink to &quot;Mock Design Spec&quot;">​</a></h1><blockquote><p><a href="./MOCK-DESIGN">🇬🇧 English</a> • <a href="./MOCK-DESIGN.ja">🇯🇵 日本語</a></p></blockquote><p>How kiwa decides <strong>what to mock and at what fidelity</strong> for third-party wallets and AA SDKs (WalletConnect, Safe, thirdweb, Privy, Biconomy, …). This document is the single source of truth referenced by Phase D-3 implementation PRs.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Each wallet / SDK is classified into one of <strong>3 mock fidelity levels</strong> based on a 5-criterion score. The classification determines whether kiwa adopts the real SDK (Level A), ships a compatible mock (Level B), or only exposes a behavioral pattern (Level C).</p><table tabindex="0"><thead><tr><th>Level</th><th>Approach</th><th>SDK dependency</th><th>Fidelity</th><th>Maintenance cost</th></tr></thead><tbody><tr><td><strong>A — Real SDK Integration</strong></td><td><code>peerDependencies</code> + selective stubs (relay / bundler / paymaster)</td><td>Yes</td><td>High</td><td>High (track SDK breaking changes)</td></tr><tr><td><strong>B — Compatible Mock</strong></td><td>Mimic the SDK&#39;s public interface, internal mock</td><td>No</td><td>Medium</td><td>Medium</td></tr><tr><td><strong>C — Behavioral Pattern</strong></td><td>Expose only the abstract pattern (multi-sig, embedded wallet, …)</td><td>No</td><td>Low</td><td>Low</td></tr></tbody></table><hr><h2 id="why-this-spec-exists" tabindex="-1">Why this spec exists <a class="header-anchor" href="#why-this-spec-exists" aria-label="Permalink to &quot;Why this spec exists&quot;">​</a></h2><p>Real dApp users adopt smart wallets (Safe, thirdweb inAppWallet, Biconomy, …) and connectors (WalletConnect v2) far beyond plain MetaMask. A naïve kiwa response would be &quot;mock everything as faithfully as possible&quot;, but that path leads to:</p><ul><li>SDK breaking changes silently rotting fixtures every quarter</li><li>Install size bloat (Web3Auth, Pimlico, etc. each weigh hundreds of KB)</li><li>False-positive risk when the mock and the real SDK diverge</li></ul><p>To stay sustainable, kiwa needs a <strong>decision protocol</strong> for each new wallet / SDK request.</p><h2 id="_5-criterion-scoring" tabindex="-1">5-criterion scoring <a class="header-anchor" href="#_5-criterion-scoring" aria-label="Permalink to &quot;5-criterion scoring&quot;">​</a></h2><p>For each candidate wallet / SDK, score 0 / 1 for the following five criteria. The <strong>total score selects the fidelity level</strong>.</p><table tabindex="0"><thead><tr><th>#</th><th>Criterion</th><th>+1 condition</th></tr></thead><tbody><tr><td>1</td><td>SDK API stability</td><td>Minor refactors land at most once per quarter</td></tr><tr><td>2</td><td>User base size</td><td>Monthly active dApps &gt; 10k</td></tr><tr><td>3</td><td>SDK-provided test mode</td><td>The SDK officially ships a test fixture / sandbox</td></tr><tr><td>4</td><td>Install size impact</td><td>Adding the SDK to peerDeps costs &lt; 500 KB gzipped</td></tr><tr><td>5</td><td>Distinct use-case count</td><td>The SDK exposes 3+ patterns relevant to dApp tests (sign / send / multi-account / paymaster / …)</td></tr></tbody></table><p><strong>Total</strong> → fidelity level:</p><ul><li><strong>3+</strong> → Level A (Real SDK Integration)</li><li><strong>1–2</strong> → Level B (Compatible Mock)</li><li><strong>0</strong> → Level C (Behavioral Pattern)</li></ul><p>Border cases (exactly 3) prefer Level B when install size is the main risk.</p><h2 id="wallet-sdk-classification-initial-allocation" tabindex="-1">Wallet / SDK classification (initial allocation) <a class="header-anchor" href="#wallet-sdk-classification-initial-allocation" aria-label="Permalink to &quot;Wallet / SDK classification (initial allocation)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Wallet / SDK</th><th>API stability</th><th>Users</th><th>Test mode</th><th>Size</th><th>Use cases</th><th><strong>Total</strong></th><th><strong>Level</strong></th><th>Rationale</th></tr></thead><tbody><tr><td><strong>WalletConnect v2</strong></td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td><strong>5</strong></td><td><strong>B</strong> (pivoted from A)</td><td>Score 5 originally targeted Level A, but the first implementation attempt (PR #168 cycle) showed install-size + SDK breaking-change cost outweighed the fidelity gain. Re-classified as Level B with an in-memory relay mock; see <code>examples/nextjs-walletconnect-v2/</code>.</td></tr><tr><td><strong>Safe (Gnosis Safe)</strong></td><td>+1</td><td>+1</td><td>0</td><td>+1</td><td>0</td><td><strong>3</strong></td><td><strong>B</strong> (border)</td><td>API stable but heavy SDK; mock contracts give equivalent coverage</td></tr><tr><td><strong>thirdweb inAppWallet</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>+1</td><td><strong>2</strong></td><td><strong>B</strong></td><td>API still evolves, large bundle; behavioral mock is safer</td></tr><tr><td><strong>Privy / Dynamic</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>0</td><td><strong>1</strong></td><td><strong>B</strong></td><td>Embedded-wallet pattern is more important than SDK specifics</td></tr><tr><td><strong>Biconomy / ZeroDev / Alchemy AA</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>+1</td><td><strong>2</strong></td><td><strong>B</strong></td><td>Bundler / paymaster behavior mockable without SDK</td></tr><tr><td><strong>Coinbase Wallet</strong></td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td>0</td><td><strong>4</strong></td><td><strong>A</strong></td><td>Already covered by EIP-6963 announce, no further work needed</td></tr><tr><td><strong>Ledger / Trezor</strong></td><td>+1</td><td>0</td><td>0</td><td>0</td><td>0</td><td><strong>1</strong></td><td><strong>Out of scope</strong></td><td>HID / Bluetooth mocking impractical; defer to real-device test tools</td></tr><tr><td><strong>Phantom (EVM mixed)</strong></td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td><strong>0</strong></td><td><strong>Out of scope</strong></td><td>Solana primary; EVM scope only</td></tr></tbody></table><h2 id="level-a-—-real-sdk-integration" tabindex="-1">Level A — Real SDK Integration <a class="header-anchor" href="#level-a-—-real-sdk-integration" aria-label="Permalink to &quot;Level A — Real SDK Integration&quot;">​</a></h2><h3 id="what-kiwa-ships" tabindex="-1">What kiwa ships <a class="header-anchor" href="#what-kiwa-ships" aria-label="Permalink to &quot;What kiwa ships&quot;">​</a></h3><ul><li>The wallet / SDK is added to <code>peerDependencies</code> (the user must install it)</li><li>kiwa fixture wraps the SDK&#39;s standard entry points</li><li>Only the parts that depend on remote infra (relay / bundler / paymaster) are stubbed</li></ul><h3 id="what-kiwa-does-not-do" tabindex="-1">What kiwa does NOT do <a class="header-anchor" href="#what-kiwa-does-not-do" aria-label="Permalink to &quot;What kiwa does NOT do&quot;">​</a></h3><ul><li>Reimplement the SDK&#39;s public API</li><li>Hide the SDK behind a different name</li></ul><h3 id="example-flow-walletconnect-v2" tabindex="-1">Example flow (WalletConnect v2) <a class="header-anchor" href="#example-flow-walletconnect-v2" aria-label="Permalink to &quot;Example flow (WalletConnect v2)&quot;">​</a></h3><ol><li>The user installs <code>@walletconnect/web3wallet</code> themselves</li><li>kiwa provides an in-memory relay stub so no real WalletConnect cloud project is required</li><li>The user calls <code>walletKit.pair(...)</code> in their test as if connecting a real wallet</li><li>kiwa routes session proposals / responses through the stub</li></ol><h3 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pro</th><th>Con</th></tr></thead><tbody><tr><td>Real SDK bugs are reproducible</td><td>Quarterly SDK upgrades may break tests</td></tr><tr><td>Tests look identical to production code</td><td>Install size grows</td></tr><tr><td>Documentation matches official SDK docs</td><td>kiwa cannot ship for users who can&#39;t install the SDK</td></tr></tbody></table><h2 id="level-b-—-compatible-mock" tabindex="-1">Level B — Compatible Mock <a class="header-anchor" href="#level-b-—-compatible-mock" aria-label="Permalink to &quot;Level B — Compatible Mock&quot;">​</a></h2><h3 id="what-kiwa-ships-1" tabindex="-1">What kiwa ships <a class="header-anchor" href="#what-kiwa-ships-1" aria-label="Permalink to &quot;What kiwa ships&quot;">​</a></h3><ul><li>A mock module that <strong>exposes the same TypeScript interface as the real SDK</strong> (at a coarse level)</li><li>Backing implementation written by kiwa contributors (deploys mock contracts, returns deterministic data)</li></ul><h3 id="what-kiwa-does-not-do-1" tabindex="-1">What kiwa does NOT do <a class="header-anchor" href="#what-kiwa-does-not-do-1" aria-label="Permalink to &quot;What kiwa does NOT do&quot;">​</a></h3><ul><li>Track every minor / patch release of the upstream SDK</li><li>Guarantee bit-for-bit compatibility with production transactions</li></ul><h3 id="example-flow-safe" tabindex="-1">Example flow (Safe) <a class="header-anchor" href="#example-flow-safe" aria-label="Permalink to &quot;Example flow (Safe)&quot;">​</a></h3><ol><li>kiwa ships <code>examples/nextjs-safe-multisig/</code> with stub Safe contracts (threshold + module + guard semantics)</li><li>The fixture exposes a <code>useSafe()</code>-style hook with the same shape as <code>@safe-global/safe-react-hooks</code></li><li>Multi-sig threshold signing, module execution, and guard rejection are tested against the mock contracts</li><li>Users porting tests to production-grade Safe replace the import with the real <code>@safe-global/safe-react-hooks</code></li></ol><h3 id="trade-offs-1" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs-1" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pro</th><th>Con</th></tr></thead><tbody><tr><td>No SDK dependency, smaller install</td><td>Mock and real SDK may diverge over time</td></tr><tr><td>Stable maintenance cost</td><td>False-positive risk if a real-SDK quirk isn&#39;t reproduced</td></tr><tr><td>Behaviorally faithful enough for CI flake elimination</td><td>Production bug reproduction limited</td></tr></tbody></table><h2 id="level-c-—-behavioral-pattern" tabindex="-1">Level C — Behavioral Pattern <a class="header-anchor" href="#level-c-—-behavioral-pattern" aria-label="Permalink to &quot;Level C — Behavioral Pattern&quot;">​</a></h2><h3 id="what-kiwa-ships-2" tabindex="-1">What kiwa ships <a class="header-anchor" href="#what-kiwa-ships-2" aria-label="Permalink to &quot;What kiwa ships&quot;">​</a></h3><ul><li>A generic helper / pattern that captures the <strong>shape</strong> of a wallet category (e.g. &quot;multi-sig threshold signing&quot;, &quot;embedded wallet with key escrow&quot;)</li><li>No reference to any specific SDK by name</li></ul><h3 id="what-kiwa-does-not-do-2" tabindex="-1">What kiwa does NOT do <a class="header-anchor" href="#what-kiwa-does-not-do-2" aria-label="Permalink to &quot;What kiwa does NOT do&quot;">​</a></h3><ul><li>Provide drop-in compatibility with a named SDK</li><li>Promise that real-SDK bugs surface</li></ul><h3 id="example-flow-privy-dynamic-embedded-wallets" tabindex="-1">Example flow (Privy / Dynamic embedded wallets) <a class="header-anchor" href="#example-flow-privy-dynamic-embedded-wallets" aria-label="Permalink to &quot;Example flow (Privy / Dynamic embedded wallets)&quot;">​</a></h3><p>kiwa documents the general &quot;embedded wallet&quot; pattern (private key stored server-side, signature requests round-tripped via a stub auth endpoint) without referencing Privy or Dynamic by name. Users adapt the pattern to whichever SDK they use.</p><h3 id="trade-offs-2" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs-2" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pro</th><th>Con</th></tr></thead><tbody><tr><td>Lowest maintenance burden</td><td>Users must adapt the pattern to their SDK themselves</td></tr><tr><td>Future-proof against SDK shifts</td><td>Real-SDK-specific behavior is invisible</td></tr><tr><td>Doubles as teaching material</td><td>Less attractive than &quot;drop-in Safe support&quot;</td></tr></tbody></table><h2 id="false-positive-boundaries" tabindex="-1">False-positive boundaries <a class="header-anchor" href="#false-positive-boundaries" aria-label="Permalink to &quot;False-positive boundaries&quot;">​</a></h2><p>Each level has known divergences from real environments. We document them so users can decide whether kiwa is enough or whether they also need staging tests on real infra.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Level A</th><th>Level B</th><th>Level C</th></tr></thead><tbody><tr><td>Real relay network failure (timeouts, dropped sessions)</td><td>❌ in-memory stub only</td><td>❌ N/A</td><td>❌ N/A</td></tr><tr><td>Real bundler revert on bundler-policy violations</td><td>❌ stub bundler accepts everything</td><td>❌ same</td><td>❌ same</td></tr><tr><td>Real paymaster gas estimation errors</td><td>❌ paymaster mocked permissive</td><td>❌ same</td><td>❌ same</td></tr><tr><td>Smart account upgrade hooks</td><td>✅ via real SDK</td><td>⚠️ depends on mock fidelity</td><td>❌ pattern only</td></tr><tr><td>RPC provider rate limiting</td><td>❌ never reproduced</td><td>❌ same</td><td>❌ same</td></tr></tbody></table><p>Users who need to verify these boundaries should run <strong>staging tests against real testnets</strong> in addition to kiwa CI.</p><h2 id="decision-when-adding-a-new-wallet-sdk" tabindex="-1">Decision when adding a new wallet / SDK <a class="header-anchor" href="#decision-when-adding-a-new-wallet-sdk" aria-label="Permalink to &quot;Decision when adding a new wallet / SDK&quot;">​</a></h2><ol><li>Score the candidate against the 5 criteria</li><li>Pick the corresponding level (A / B / C)</li><li>Open an issue with the title <code>feat(wallet-support): &lt;name&gt; at Level &lt;X&gt;</code> and tag it with <code>wallet-support</code></li><li>Phase D maintainers review the score within 1 week</li><li>Implementation PR cites this spec in the description</li></ol><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Scope</th><th>Target</th></tr></thead><tbody><tr><td><strong>D-3a</strong></td><td>WalletConnect v2 at Level B (compatible mock — pivoted from Level A due to install-size + SDK breaking-change cost; see <code>examples/nextjs-walletconnect-v2/</code>)</td><td><code>examples/nextjs-walletconnect-v2/</code></td></tr><tr><td><strong>D-3b</strong></td><td>Safe at Level B</td><td><code>examples/nextjs-safe-multisig/</code></td></tr><tr><td><strong>D-3c</strong></td><td>thirdweb at Level B</td><td><code>examples/nextjs-thirdweb-aa/</code></td></tr><tr><td><strong>D-3d</strong></td><td>Privy / Dynamic at Level C</td><td>docs cookbook chapter only</td></tr><tr><td><strong>D-3e</strong></td><td>Biconomy / ZeroDev / Alchemy at Level B</td><td><code>examples/nextjs-aa-paymaster/</code></td></tr><tr><td><strong>D-4</strong></td><td>Mainnet-fork AA full flow</td><td><code>examples/nextjs-aa-mainnet-fork/</code></td></tr></tbody></table><p>Phases are sequenced based on user-base size, not difficulty. WalletConnect v2 ships first because it unlocks the largest population.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./COMPARISON"><code>docs/COMPARISON.md</code></a> — How kiwa compares with Synpress / wallet-mock</li><li><a href="./../.claude/skills/kiwa-play/references/adversarial-pitfalls"><code>.claude/skills/kiwa-play/references/adversarial-pitfalls.md</code></a> — 9 false-positive patterns + self-check</li><li><a href="./en/cookbook/smart-wallet-aa"><code>docs/en/cookbook/smart-wallet-aa.md</code></a> — Existing AA (ERC-4337) test pattern</li></ul>',57)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
